const dir='/Users/tanishqpalandurkar/Movies/hermes-isolation-2026-10-03';
const config=JSON.parse(readFileSync(resolve(dir,process.argv[2]??'yyoreel.config.json'),'utf8'));
const selected=process.argv.slice(3); const chrome=await launchChrome({headless:false});
let client,recorder;
try{
 client=await connectCDP(chrome.port); await client.Page.enable();await client.Runtime.enable();
 for(const [name,v] of Object.entries(config.videos)){
  if(selected.length&&!selected.includes(name))continue;
  console.log('Preparing',name);
  const zoom=v.zoom??1,width=1600,height=900;
  await client.Emulation.clearDeviceMetricsOverride();
  await client.Emulation.setDeviceMetricsOverride({width:Math.round(width/zoom),height:Math.round(height/zoom),deviceScaleFactor:zoom,mobile:false});
  await navigate(client,v.url);await waitForSelector(client,v.waitFor);await pause(2200);
  console.log('Page state',JSON.stringify((await client.Runtime.evaluate({expression:'JSON.stringify({title:document.title,scrollY,innerWidth,innerHeight,text:document.body.innerText.slice(0,100)})'})).result.value));
  const ctx=new RecordingContext();ctx.setMode('record');ctx.setCursorPosition(80,80);
  const timeline=new InteractionTimeline(width,height,{fps:v.fps,zoom,autoZoom:false,background:'none',hud:{enabled:false},initialCursor:{x:80,y:80}});ctx.setTimeline(timeline);
  recorder=new Recorder(width,height,{fps:v.fps,captureFormat:'png',preferScreenshots:true,crf:11});recorder.setTimeline(timeline);
  const output=resolve(dir,'clips',name+'.mp4');await recorder.start(client,output,ctx);
  for(const step of v.steps){
   console.log(name,step.action,step.ms??step.selector??step.text??'');
   if(step.action==='pause')await pause(step.ms);
   else if(step.action==='screenshot')await captureScreenshot(client,resolve(dir,step.output));
   else if(step.action==='moveTo'){
    const box=step.selector?await findElementBySelector(client,step.selector):await findElementByText(client,step.text);
    if(!box)throw new Error('Target missing');await moveCursorTo(ctx,client,box.x+Math.min(box.width/2,300),box.y+box.height/2);
   }
  }
  await recorder.stop();const data=timeline.toJSON();console.log('Captured frames',data.frames.length,'seconds',data.frames.length/v.fps);
  mkdirSync(resolve(dir,'.yyoreel/raw'),{recursive:true});mkdirSync(resolve(dir,'.yyoreel/timelines'),{recursive:true});
  const raw=resolve(dir,'.yyoreel/raw',name+'.mp4');moveFileSync(recorder.getTempVideoPath(),raw);recorder=null;
  writeFileSync(resolve(dir,'.yyoreel/timelines',name+'.timeline.json'),JSON.stringify(data));await compose(raw,data,output,{crf:11,preset:'veryfast'});
  console.log('Done',output);
 }
}finally{if(recorder)await recorder.stop();if(client)await client.close();chrome.kill()}

