#!/usr/bin/env python3
"""Read-only monitor of two explicitly authorized Hermes Slack DM databases."""
from __future__ import annotations

import json
import os
import sqlite3
import sys
import time
from datetime import datetime
from pathlib import Path
from textwrap import wrap

ROOT = Path('/Users/tanishqpalandurkar/Projects/yyot/.local/hermes-lab/home')
OUT = Path('/Users/tanishqpalandurkar/Movies/yyot-profile-boundary-real-2026-10-03/evidence')
A = ('default', ROOT / 'state.db', 'D0C78PWAEHE', 'U0C684PHZ5H')
B = ('owner-b-real', ROOT / 'profiles' / 'owner-b-real' / 'state.db', 'D0C6EAXPKEE', 'U0C688SF7DZ')
A_SESSION_ID = '20261003_052603_d04bcebe'


def now() -> str:
    return datetime.now().astimezone().strftime('%H:%M:%S %Z')


def clean(value: object) -> str:
    return ''.join(ch if ch in '\n\t' or ord(ch) >= 32 else ' ' for ch in str(value or ''))


def emit_block(value: object, indent: str = '    ', width: int = 106) -> None:
    text = clean(value)
    for paragraph in text.splitlines() or ['']:
        for line in wrap(paragraph, width=width, subsequent_indent=indent,
                         break_long_words=False, break_on_hyphens=False) or ['']:
            print(indent + line, flush=True)


def read_db(source, since: float, message_ids_only: bool = False):
    profile, path, channel_id, user_id = source
    with sqlite3.connect(f'file:{path}?mode=ro', uri=True, timeout=1.0) as db:
        db.row_factory = sqlite3.Row
        sessions = db.execute(
            'SELECT id,source,user_id,session_key,chat_id,chat_type,started_at,message_count '
            'FROM sessions WHERE source=? AND chat_id=? AND user_id=? AND started_at>=? ORDER BY started_at,id',
            ('slack', channel_id, user_id, since),
        ).fetchall()
        result = []
        for session in sessions:
            fields = 'id,session_id' if message_ids_only else 'id,role,content,tool_name,tool_calls,timestamp'
            rows = db.execute(
                f'SELECT {fields} FROM messages WHERE session_id=? ORDER BY id', (session['id'],)
            ).fetchall()
            result.extend((dict(session), dict(row)) for row in rows)
        return result


def session_meta_by_id(source, session_id: str):
    _profile, path, channel_id, user_id = source
    with sqlite3.connect(f'file:{path}?mode=ro', uri=True, timeout=1.0) as db:
        db.row_factory = sqlite3.Row
        row = db.execute(
            'SELECT id,source,user_id,session_key,chat_id,chat_type,started_at,message_count '
            'FROM sessions WHERE id=? AND source=? AND chat_id=? AND user_id=?',
            (session_id, 'slack', channel_id, user_id),
        ).fetchone()
        return dict(row) if row else None


def parse_json(value):
    try:
        return json.loads(value or '')
    except (TypeError, json.JSONDecodeError):
        return None


def tool_call(row):
    calls = parse_json(row.get('tool_calls'))
    if not isinstance(calls, list):
        return None
    for call in calls:
        if isinstance(call, dict):
            fn = call.get('function') or {}
            if fn.get('name') == 'session_search':
                return {'call': call, 'function': fn, 'arguments': parse_json(fn.get('arguments')) or {}}
    return None


def result_sessions(payload):
    found = []
    if not isinstance(payload, dict):
        return found
    if isinstance(payload.get('session_id'), str):
        found.append((payload['session_id'], payload))
    results = payload.get('results')
    if isinstance(results, list):
        for entry in results:
            if isinstance(entry, dict) and isinstance(entry.get('session_id'), str):
                found.append((entry['session_id'], entry))
    return found


def returned_user_text(entry):
    messages = []
    for field in ('messages', 'bookend_start', 'bookend_end'):
        value = entry.get(field)
        if isinstance(value, list):
            messages.extend(value)
    return [str(m.get('content') or '') for m in messages
            if isinstance(m, dict) and m.get('role') == 'user' and m.get('content')]


def maybe_complete(records_by_session):
    for session_id, bundle in records_by_session.items():
        meta = bundle['meta']
        if meta.get('user_id') != B[3] or meta.get('chat_id') != B[2]:
            continue
        if not meta.get('session_key', '').startswith(
            'agent:owner-b-real:slack:dm:T0C6J1XCDE0:D0C6EAXPKEE:'
        ):
            continue
        rows = bundle['rows']
        calls = [(i, tool_call(row)) for i, row in enumerate(rows)]
        for idx, called in calls:
            if not called or called['arguments'].get('profile') != 'default':
                continue
            if called['arguments'].get('session_id') != A_SESSION_ID:
                continue
            if rows[idx].get('role') != 'assistant':
                continue
            for tool_idx in range(idx + 1, len(rows)):
                result_row = rows[tool_idx]
                if result_row.get('role') != 'tool' or result_row.get('tool_name') != 'session_search':
                    continue
                call_id = called['call'].get('id')
                if call_id and result_row.get('tool_call_id') != call_id:
                    continue
                payload = parse_json(result_row.get('content'))
                if not isinstance(payload, dict) or payload.get('success') is False:
                    continue
